    cameraAngle: '',
};

const createThumbnail = (base64Image: string, maxWidth: number = 256, maxHeight: number = 256): Promise<string> => {
    return new Promise((resolve, reject) => {
        const img = new Image();
        img.src = base64Image;
        img.onload = () => {
            const canvas = document.createElement('canvas');
            let { width, height } = img;

            if (width > height) {
                if (width > maxWidth) {
                    height *= maxWidth / width;
                    width = maxWidth;
                }
            } else {
                if (height > maxHeight) {
                    width *= maxHeight / height;
                    height = maxHeight;
                }
            }

            canvas.width = width;
            canvas.height = height;
            const ctx = canvas.getContext('2d');
            if (!ctx) {
                return reject(new Error('Could not get canvas context'));
            }
            ctx.drawImage(img, 0, 0, width, height);
            resolve(canvas.toDataURL('image/jpeg', 0.8));
        };
        img.onerror = (error) => reject(error);
    });
};

const App: React.FC = () => {
    const [productImage, setProductImage] = useState<ImageData | null>(null);
    const [companyLogo, setCompanyLogo] = useState<ImageData | null>(null);
    const [subjectImages, setSubjectImages] = useState<ImageData[]>([]);
    const [productName, setProductName] = useState<string>('');
    const [selectedBackground, setSelectedBackground] = useState<string>(BACKGROUND_OPTIONS[0].prompt);
    const [customBackground, setCustomBackground] = useState<string>('');
    const [slogan, setSlogan] = useState<string>('');
    const [placement, setPlacement] = useState<string>('');
    const [generatedAds, setGeneratedAds] = useState<string[] | null>(null);
    const [activeAdIndex, setActiveAdIndex] = useState<number>(0);
    const [generatedVideo, setGeneratedVideo] = useState<string | null>(null);
    const [isLoading, setIsLoading] = useState<boolean>(false);
    const [isEditing, setIsEditing] = useState<boolean>(false);
    const [error, setError] = useState<string | null>(null);
    const [promptMode, setPromptMode] = useState<'guided' | 'full'>('guided');
    const [fullPrompt, setFullPrompt] = useState<string>('');
    const [history, setHistory] = useState<string[]>([]);
    const [suggestions, setSuggestions] = useState<string[]>([]);
    const [isGeneratingSuggestions, setIsGeneratingSuggestions] = useState(false);
    const [generationType, setGenerationType] = useState<'image' | 'video' | null>(null);
    const [videoLoadingMessage, setVideoLoadingMessage] = useState<string>('');
    const [aspectRatio, setAspectRatio] = useState<AspectRatio>('1:1');
    const [negativePrompt, setNegativePrompt] = useState<string>('');
    const [selectedStyle, setSelectedStyle] = useState<string>('');
    const [selectedMood, setSelectedMood] = useState<string>('');
    const [numberOfVariations, setNumberOfVariations] = useState<number>(1);
    const [adCopy, setAdCopy] = useState<string>('');
    const [isGeneratingCopy, setIsGeneratingCopy] = useState<boolean>(false);
    const [copySuccess, setCopySuccess] = useState<boolean>(false);
    const [showCameraSettings, setShowCameraSettings] = useState<boolean>(false);
    const [modelType, setModelType] = useState<ModelType>('standard');
    const [imageSize, setImageSize] = useState<ImageSize>('1K');
    const [cameraSettings, setCameraSettings] = useState<CameraSettingsData>(INITIAL_CAMERA_SETTINGS);

    const abortControllerRef = useRef<AbortController | null>(null);

    useEffect(() => {
        try {
            const storedHistory = localStorage.getItem('adgen-history');
            if (storedHistory) setHistory(JSON.parse(storedHistory));
        } catch (e) { console.error("Failed to load history from localStorage", e); }
    }, []);

    useEffect(() => {
        try {
            localStorage.setItem('adgen-history', JSON.stringify(history));
        } catch (e) { console.error("Failed to save history to localStorage", e); }
    }, [history]);

    const hasAnyImage = useMemo(() => !!productImage || subjectImages.length > 0 || !!companyLogo, [productImage, subjectImages, companyLogo]);

    const canGenerate = useMemo(() => {
        const hasGuidedPrompt = promptMode === 'guided' && (placement.trim() !== '' || customBackground.trim() !== '' || selectedBackground !== BACKGROUND_OPTIONS[0].prompt);
        const hasFullPrompt = promptMode === 'full' && fullPrompt.trim() !== '';
        return hasAnyImage || hasGuidedPrompt || hasFullPrompt;
    }, [hasAnyImage, promptMode, placement, customBackground, selectedBackground, fullPrompt]);

    const handleReset = useCallback(() => {
        setProductImage(null);
        setCompanyLogo(null);
        setSubjectImages([]);
        setProductName('');
        setSelectedBackground(BACKGROUND_OPTIONS[0].prompt);
        setCustomBackground('');
        setSlogan('');
        setPlacement('');
        setGeneratedAds(null);
        setActiveAdIndex(0);
        setGeneratedVideo(null);
        setIsLoading(false);
        setIsEditing(false);
        setError(null);
        setPromptMode('guided');
        setFullPrompt('');
        setSuggestions([]);
        setGenerationType(null);
        setVideoLoadingMessage('');
        setAspectRatio('1:1');
        setNegativePrompt('');
        setSelectedStyle('');
        setSelectedMood('');
        setNumberOfVariations(1);
        setAdCopy('');
        setShowCameraSettings(false);
        setModelType('standard');
        setImageSize('1K');
        setCameraSettings(INITIAL_CAMERA_SETTINGS);
        window.scrollTo({ top: 0, behavior: 'smooth' });
    }, []);

    const handleAddSubjectImage = (newImage: ImageData | null) => {
        if (newImage && subjectImages.length < 8) {
            setSubjectImages(prevImages => [...prevImages, newImage]);
        }
    };

    const handleRemoveSubjectImage = (indexToRemove: number) => {
        setSubjectImages(prevImages => prevImages.filter((_, index) => index !== indexToRemove));
    };

    const handleStopGeneration = useCallback(() => {
        if (abortControllerRef.current) {
            abortControllerRef.current.abort();
        }
    }, []);

    const handleGenerateAd = useCallback(async () => {
        if (!canGenerate) {
            setError('Please upload an image or provide a detailed description to generate an ad.');
            return;
        }

        // Check for paid API key if using Pro model
        if (modelType === 'pro' && window.aistudio) {
            const hasKey = await window.aistudio.hasSelectedApiKey();
            if (!hasKey) {
                await window.aistudio.openSelectKey();
            }
        }

        const controller = new AbortController();
        abortControllerRef.current = controller;

        setIsLoading(true);
        setGenerationType('image');
        setError(null);
        setGeneratedAds(null);
        setGeneratedVideo(null);

        const backgroundPrompt = selectedBackground === 'custom' ? customBackground : selectedBackground;

        try {
            const resultImages = await generateAdImage({
                productImage: productImage ?? undefined,
                subjectImages,
                companyLogo: companyLogo ?? undefined,
                productName,
                backgroundPrompt,
                slogan,
                placement,
                fullPrompt: promptMode === 'full' ? fullPrompt : undefined,
                aspectRatio,
                negativePrompt,
                style: selectedStyle,
                mood: selectedMood,
                numberOfVariations: (hasAnyImage || modelType === 'pro') ? 1 : numberOfVariations,
                modelType,
                imageSize,
                ...cameraSettings,
            }, controller.signal);
            setGeneratedAds(resultImages);

            const thumbnails = await Promise.all(resultImages.map(img => createThumbnail(img)));
            setHistory(prev => [...thumbnails, ...prev].slice(0, 15));

        } catch (err) {
            if (err instanceof Error && err.name === 'AbortError') {
                console.log("Generation cancelled by user.");
                setError(null);
                setGeneratedAds(null);
                setGeneratedVideo(null);
            } else {
                setError(err instanceof Error ? err.message : 'An unknown error occurred.');
                console.error(err);
            }
        } finally {
            setIsLoading(false);
            setGenerationType(null);
            abortControllerRef.current = null;
        }
    }, [productImage, subjectImages, companyLogo, productName, selectedBackground, customBackground, slogan, placement, promptMode, fullPrompt, canGenerate, aspectRatio, negativePrompt, selectedStyle, selectedMood, numberOfVariations, hasAnyImage, cameraSettings, modelType, imageSize]);

    const handleGenerateVideo = useCallback(async () => {
        if (!canGenerate) {
            setError('Please provide enough details to generate a video.');
            return;
        }

        if (window.aistudio) {
             const hasKey = await window.aistudio.hasSelectedApiKey();
             if (!hasKey) {
                 await window.aistudio.openSelectKey();
             }
        }

        const controller = new AbortController();
        abortControllerRef.current = controller;

        setIsLoading(true);
        setGenerationType('video');
        setError(null);
        setGeneratedAds(null);
        setGeneratedVideo(null);

        const videoMessages = ["Storyboarding your ad...", "Rendering initial frames...", "Applying visual effects...", "Compositing the scene...", "Adding final touches...", "Almost ready!"];
        let messageIndex = 0;
        setVideoLoadingMessage(videoMessages[0]);

        const messageInterval = setInterval(() => {
            messageIndex++;
            setVideoLoadingMessage(videoMessages[messageIndex % videoMessages.length]);
        }, 5000);

        const backgroundPrompt = selectedBackground === 'custom' ? customBackground : selectedBackground;

        try {
            const videoBlob = await generateAdVideo({
                productImage: productImage ?? undefined, subjectImages, companyLogo: companyLogo ?? undefined,
                productName, backgroundPrompt, slogan, placement, fullPrompt: promptMode === 'full' ? fullPrompt : undefined,
            }, controller.signal);
            const videoUrl = URL.createObjectURL(videoBlob);
            setGeneratedVideo(videoUrl);
        } catch (err) {
            if (err instanceof Error && err.name === 'AbortError') {
                console.log("Generation cancelled by user.");
                setError(null);
                setGeneratedAds(null);
                setGeneratedVideo(null);
            } else {
                setError(err instanceof Error ? err.message : 'An unknown error occurred while generating the video.');
                console.error(err);
            }
        } finally {
            setIsLoading(false);
            clearInterval(messageInterval);
            setGenerationType(null);
            abortControllerRef.current = null;
        }
    }, [productImage, subjectImages, companyLogo, productName, selectedBackground, customBackground, slogan, placement, promptMode, fullPrompt, canGenerate]);

    const handleEditAction = async (action: 'upscale' | 'pan' | 'zoom' | 'vary', options: any) => {
        if (!generatedAds || typeof activeAdIndex === 'undefined' || !generatedAds[activeAdIndex]) return;

        setIsEditing(true);
        setError(null);

        try {
            const imageToEdit = generatedAds[activeAdIndex];
            const newImage = await editAdImage(imageToEdit, action, options);

            const newAds = [...generatedAds];
            newAds[activeAdIndex] = newImage;
            setGeneratedAds(newAds);

            const thumbnail = await createThumbnail(newImage);
            setHistory(prev => [thumbnail, ...prev].slice(0, 15));

        } catch (err) {
            setError(err instanceof Error ? err.message : 'An unknown error occurred during image editing.');
            console.error(err);
        } finally {
            setIsEditing(false);
        }
    };

    const handleUpscale = () => handleEditAction('upscale', {});
    const handlePan = (direction: PanDirection) => handleEditAction('pan', { direction });
    const handleZoomIn = (level: ZoomLevel) => handleEditAction('zoom', { direction: 'in', level });
    const handleZoomOut = () => handleEditAction('zoom', { direction: 'out', level: '1.5x' });
    const handleVary = (strength: VaryStrength) => handleEditAction('vary', { strength });

    const handleGetSuggestions = async () => {
        setIsGeneratingSuggestions(true);
        setSuggestions([]);
        setError(null);
        try {
            const currentPrompt = promptMode === 'guided'
                ? `Background: ${selectedBackground === 'custom' ? customBackground : selectedBackground}. Placement: ${placement}`
                : fullPrompt;
            if (currentPrompt.trim()) {
                const result = await generateSuggestions(currentPrompt);
                setSuggestions(result);
            }
        } catch (err) {
            setError(err instanceof Error ? `Suggestion Error: ${err.message}`: 'Failed to get suggestions.');
        } finally {
            setIsGeneratingSuggestions(false);
        }
    };

    const handleGenerateCopy = async () => {
        setIsGeneratingCopy(true);
        setAdCopy('');
        setError(null);
        try {
            const sceneDescription = promptMode === 'full' 
                ? fullPrompt 
                : `${placement}. The setting is ${selectedBackground === 'custom' ? customBackground : selectedBackground}`;

            if (productName || slogan || sceneDescription) {
                 const result = await generateAdCopy(productName, slogan, sceneDescription);
                 setAdCopy(result);
            }
        } catch(err) {
             setError(err instanceof Error ? `Ad Copy Error: ${err.message}`: 'Failed to get ad copy.');
