import React, { useState, useCallback, useRef, useEffect } from 'react';
import type { ImageData } from '../types';
import { UploadIcon, CloseIcon } from './icons';

interface ImageUploaderProps {
    id: string;
    label: string;
    onImageUpload: (imageData: ImageData | null) => void;
    initialImage?: ImageData | null;
}

const fileToBase64 = (file: File): Promise<string> => {
    return new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.readAsDataURL(file);
        reader.onload = () => resolve((reader.result as string).split(',')[1]);
        reader.onerror = error => reject(error);
    });
};

export const ImageUploader: React.FC<ImageUploaderProps> = ({ id, label, onImageUpload, initialImage }) => {
    const [preview, setPreview] = useState<string | null>(null);
    const [fileName, setFileName] = useState<string | null>(null);
    const fileInputRef = useRef<HTMLInputElement>(null);

    // Sync preview if initialImage changes (e.g., reset)
    useEffect(() => {
        if (!initialImage) {
            setPreview(null);
            setFileName(null);
        } else {
            // If we have an initial image but no preview (e.g. on load or from history), 
            // construct it if needed, but for reset we mainly care about null.
            setPreview(`data:${initialImage.mimeType};base64,${initialImage.base64}`);
        }
    }, [initialImage]);

    const handleFileChange = useCallback(async (event: React.ChangeEvent<HTMLInputElement>) => {
        const file = event.target.files?.[0];
        if (file) {
            try {
                if(file.size > 4 * 1024 * 1024) {
                    alert("File size exceeds 4MB limit.");
                    return;
                }
                const base64 = await fileToBase64(file);
                const imageData: ImageData = { base64, mimeType: file.type };
                onImageUpload(imageData);
                setPreview(URL.createObjectURL(file));
                setFileName(file.name);
            } catch (error) {
                console.error('Error converting file to base64:', error);
                onImageUpload(null);
                setPreview(null);
                setFileName(null);
            }
        }
    }, [onImageUpload]);

    const handleClick = () => {
        fileInputRef.current?.click();
    };

    const handleRemove = useCallback((e: React.MouseEvent) => {
        e.stopPropagation(); // Prevent triggering the file dialog
        onImageUpload(null);
        setPreview(null);
        setFileName(null);
        if (fileInputRef.current) {
            fileInputRef.current.value = '';
        }
    }, [onImageUpload]);


    return (
        <div className="flex flex-col items-center justify-center w-full h-full">
            <label htmlFor={id} className="text-sm font-medium text-brand-light mb-2">{label}</label>
            <div
                onClick={handleClick}
                className="relative flex flex-col items-center justify-center w-full h-full border-2 border-dashed border-gray-500 rounded-lg cursor-pointer bg-brand-primary hover:bg-gray-800 transition-colors"
            >
                {preview ? (
                    <>
                        <img src={preview} alt="Preview" className="object-contain h-full w-full rounded-lg" />
                        <button 
                            onClick={handleRemove} 
                            className="absolute top-2 right-2 bg-black bg-opacity-70 rounded-full p-1 text-white hover:bg-red-600 transition-colors"
                            aria-label="Remove image"
                        >
                            <CloseIcon className="w-4 h-4" />
                        </button>
                    </>
                ) : (
                    <div className="flex flex-col items-center justify-center pt-5 pb-6 text-center">
                        <UploadIcon className="w-8 h-8 mb-4 text-gray-400" />
                        <p className="mb-2 text-sm text-gray-400"><span className="font-semibold">Click to upload</span></p>
                        <p className="text-xs text-gray-500">PNG, JPG, WEBP (MAX. 4MB)</p>
                    </div>
                )}
                <input ref={fileInputRef} id={id} type="file" className="hidden" onChange={handleFileChange} accept="image/png, image/jpeg, image/webp" />
            </div>
             {fileName && <p className="text-xs text-gray-400 mt-2 truncate max-w-full">{fileName}</p>}
        </div>
    );
};

export interface ImageData {
  base64: string;
  mimeType: string;
}

