export const generateAdImage = async (params: GenerateAdParams, signal: AbortSignal): Promise<string[]> => {
    const { 
        productImage, subjectImages, companyLogo, productName, backgroundPrompt, slogan, 
        placement, fullPrompt, aspectRatio, negativePrompt, style, mood, numberOfVariations,
        cameraType, focalLength, aperture, shutterSpeed, lightingStyle, lightingSetup, distortion, textureDetail, colorStyle, technique, cameraAngle,
        modelType, imageSize
    } = params;

    const ai = getAIClient();
    const hasLogo = !!companyLogo;
    const hasAnyImage = !!productImage || subjectImages.length > 0 || hasLogo;
    const isPro = modelType === 'pro';

    const cameraDetails = [
        cameraType,
        cameraAngle,
        focalLength,
        aperture,
        shutterSpeed,
        lightingStyle,
        lightingSetup,
        distortion,
        textureDetail,
        colorStyle,
        technique,
    ].filter(Boolean).join(', ');


    try {
        if (signal.aborted) {
             const error = new Error("Generation cancelled by user.");
             error.name = "AbortError";
             throw error;
        }
        const abortPromise = createAbortPromise<never>(signal);

        if (isPro) {
             const imageParts: { inlineData: { data: string, mimeType: string } }[] = [];
             const imageDescriptions: string[] = [];

             if (productImage) {
                 imageParts.push({ inlineData: { data: productImage.base64, mimeType: productImage.mimeType } });
                 imageDescriptions.push('The primary product image.');
             }
             subjectImages.forEach((img, i) => {
                 imageParts.push({ inlineData: { data: img.base64, mimeType: img.mimeType } });
                 imageDescriptions.push(`A context/subject image #${i + 1}.`);
             });
             if (companyLogo) {
                 imageParts.push({ inlineData: { data: companyLogo.base64, mimeType: companyLogo.mimeType } });
                 imageDescriptions.push('The company logo.');
             }

             const sceneDescription = fullPrompt 
                 ? fullPrompt 
                 : `The main setting is: ${backgroundPrompt}. ${placement || 'The product should be the main focus, presented appealingly.'}`;

             const resolutionQualityNote = (imageSize === '6K' || imageSize === '8K') 
                 ? `Render with extreme ${imageSize} UHD resolution detail, ultra-sharp textures, and maximum pixel density.`
                 : '';

             const promptInstructions = [
                 'Task: Create a single, high-quality photorealistic advertisement image.',
                 resolutionQualityNote,
                 hasAnyImage ? 'Combine all provided images into one cohesive scene based on the description.' : 'Generate the scene based on the description.',
                 `Scene Description: ${sceneDescription}`,
                 aspectRatio === '97:60' ? 'Format: Optimize the composition for an Amazon Infographic (970x600 pixels). Ensure centered focus with breathable space on the sides for technical callouts and text overlays.' : '',
                 hasAnyImage ? 'Image Roles: ' + imageDescriptions.join(' ') : '',
                 style ? `Artistic Style: ${style}.` : '',
                 mood ? `Overall Mood: ${mood}.` : '',
                 cameraDetails ? `Camera & Lighting: ${cameraDetails}.` : '',
                 negativePrompt ? `Important Exclusion: The image must NOT contain ${negativePrompt}.` : '',
                 hasLogo ? 'Logo Integration: Place the company logo tastefully in the scene.' : '',
                 slogan ? `Slogan: Add the text "${slogan}" to the image. The text must be stylish and legible.` : 'Do not add any text.',
             ].filter(Boolean);

             const textPrompt = promptInstructions.join('\n');

             // Gemini 3 Pro Request
             const response = await Promise.race([
                ai.models.generateContent({
                    model: 'gemini-3-pro-image-preview',
                    contents: { parts: [...imageParts, { text: textPrompt }] },
                    config: {
                        imageConfig: {
                            imageSize: mapToApiImageSize(imageSize),
                            aspectRatio: mapToApiAspectRatio(aspectRatio),
                        }
                    },
                }),
                abortPromise
             ]);

             const images: string[] = [];
             for (const part of response.candidates?.[0]?.content?.parts || []) {
                 if (part.inlineData) {
                     images.push(`data:${part.inlineData.mimeType};base64,${part.inlineData.data}`);
                 }
             }

             if (images.length === 0) {
                 throw new Error("The Pro model did not return an image.");
             }
             return images;

        } else if (hasAnyImage) {
            // Standard Model: Image Editing / Composition (Gemini 2.5 Flash)
            const imageParts: { inlineData: { data: string, mimeType: string } }[] = [];
            const imageDescriptions: string[] = [];

            if (productImage) {
                imageParts.push({ inlineData: { data: productImage.base64, mimeType: productImage.mimeType } });
                imageDescriptions.push('The primary product image.');
            }
            subjectImages.forEach((img, i) => {
                imageParts.push({ inlineData: { data: img.base64, mimeType: img.mimeType } });
                imageDescriptions.push(`A context/subject image #${i + 1}.`);
            });
            if (companyLogo) {
                imageParts.push({ inlineData: { data: companyLogo.base64, mimeType: companyLogo.mimeType } });
                imageDescriptions.push('The company logo.');
            }

            const sceneDescription = fullPrompt 
                ? fullPrompt 
                : `The main setting is: ${backgroundPrompt}. ${placement || 'The product should be the main focus, presented appealingly.'}`;

            const promptInstructions = [
                'Task: Create a single, photorealistic advertisement image.',
                'Combine all provided images into one cohesive scene based on the description.',
                aspectRatio === '97:60' ? 'Layout: Format as an Amazon Product Infographic (970x600). Ensure the product is central and sharp.' : '',
                `Scene Description: ${sceneDescription}`,
                'Image Roles: ' + imageDescriptions.join(' '),
            ];

            if (style) promptInstructions.push(`Artistic Style: The style must be ${style}.`);
            if (mood) promptInstructions.push(`Overall Mood: The mood must be ${mood}.`);
            if (cameraDetails) promptInstructions.push(`Camera & Lighting Style: ${cameraDetails}.`);
            if (negativePrompt) promptInstructions.push(`Important Exclusion: The image must NOT contain ${negativePrompt}.`);
            if (hasLogo) promptInstructions.push('Logo Integration: Place the company logo tastefully.');
            if (slogan) {
                promptInstructions.push(`Slogan: Add the text "${slogan}" to the image.`);
            } else {
                promptInstructions.push('Slogan: Do not add any text to the image.');
            }

            promptInstructions.push('Final Output: The final image must be a single, photorealistic photograph.');

            const textPrompt = promptInstructions.join('\n');

            const generatePromise = ai.models.generateContent({
                model: 'gemini-2.5-flash-image',
                contents: { parts: [...imageParts, { text: textPrompt }] },
                config: { responseModalities: [Modality.IMAGE, Modality.TEXT] },
            });

            const response = await Promise.race([generatePromise, abortPromise]);

            for (const part of response.candidates[0].content.parts) {
                if (part.inlineData && part.inlineData.mimeType.startsWith('image/')) {
                    const base64ImageBytes: string = part.inlineData.data;
                    return [`data:${part.inlineData.mimeType};base64,${base64ImageBytes}`];
                }
            }
             // Check for text refusal
             const textPart = response.candidates[0].content.parts.find(p => p.text);
             if (textPart) throw new Error(`The AI responded with text instead of an image: ${textPart.text}`);

            throw new Error("The AI did not return an image. Try refining your prompts.");

        } else {
            // Standard Model: Text-to-Image (Imagen)
            const description = fullPrompt 
                ? fullPrompt 
                : `${placement || `A product shot of "${productName || 'a product'}"`}. The background setting is ${backgroundPrompt}.`;

            const imagenPrompt = [
                `A high-end advertisement image.`,
                aspectRatio === '97:60' ? 'Composition: Amazon Product Infographic 970x600 layout.' : '',
                `Style: ${style || 'Photorealistic'}.`,
                mood ? `Mood: ${mood}.` : '',
                `Scene description: ${description}.`,
                slogan ? `The advertisement includes the slogan: "${slogan}".` : '',
                cameraDetails ? `Camera settings: ${cameraDetails}.` : '',
                `The image must mimic a professional photograph for an advertising campaign.`,
                negativePrompt ? `Important Exclusion: The image must NOT contain ${negativePrompt}.` : ''
            ].filter(Boolean).join(' ').replace(/\s+/g, ' ');

            const generatePromise = ai.models.generateImages({
                model: 'imagen-4.0-generate-001',
                prompt: imagenPrompt,
                config: {
                  numberOfImages: numberOfVariations || 1,
                  outputMimeType: 'image/jpeg',
                  aspectRatio: mapToApiAspectRatio(aspectRatio),
                },
            });

            const response = await Promise.race([generatePromise, abortPromise]);

            if (response.generatedImages && response.generatedImages.length > 0) {
                return response.generatedImages.map(img => {
                    const base64ImageBytes: string = img.image.imageBytes;
                    return `data:image/jpeg;base64,${base64ImageBytes}`;
                });
            }
            throw new Error("The AI did not return an image from the generation model.");
        }

    } catch (error) {
        if (error instanceof Error && error.name === 'AbortError') {
            throw error;
        }
        console.error("Error generating ad image:", error);
        if (error instanceof Error) {
            try {
                const nestedError = JSON.parse(error.message);
                if (nestedError?.error?.message) {
                    throw new Error(`Failed to generate the ad image: ${nestedError.error.message}`);
                }
            } catch (e) {
                // Not a JSON error
            }
            throw new Error(`Failed to generate the ad image: ${error.message}`);
        }
        throw new Error("An unknown error occurred while generating the ad image.");
    }
};

export const generateAdVideo = async (params: GenerateAdParams, signal: AbortSignal): Promise<Blob> => {
     const { 
        productImage, productName, backgroundPrompt, slogan, placement, fullPrompt 
    } = params;

    const ai = getAIClient();

    try {
        if (signal.aborted) {
             const error = new Error("Generation cancelled by user.");
             error.name = "AbortError";
             throw error;
        }

        const sceneDescription = fullPrompt 
            ? fullPrompt 
            : `A cinematic product ad for "${productName}". The scene: ${backgroundPrompt}. ${placement}. Slogan: ${slogan}.`;

        const prompt = `Create a high-quality advertising video. ${sceneDescription}`;

        const inputImage = productImage ? {
            imageBytes: productImage.base64,
            mimeType: productImage.mimeType
        } : undefined;

        let operation = await ai.models.generateVideos({
            model: 'veo-3.1-fast-generate-preview',
            prompt: prompt,
            image: inputImage,
            config: {
                numberOfVideos: 1,
                resolution: '1080p',
                aspectRatio: '16:9',
            }
        });

        while (!operation.done) {
             if (signal.aborted) throw new Error("Generation cancelled");
             await new Promise(resolve => setTimeout(resolve, 5000));
             operation = await ai.operations.getVideosOperation({operation});
        }

        if (operation.response?.generatedVideos?.[0]?.video?.uri) {
             const videoUri = operation.response.generatedVideos[0].video.uri;
             // Must append API key for Veo downloads
             const response = await fetch(`${videoUri}&key=${process.env.API_KEY}`);
             if (!response.ok) throw new Error("Failed to download video");
             return await response.blob();
        }

        throw new Error("No video generated");

    } catch (error: any) {
        if (signal.aborted || error.name === 'AbortError') {
             const e = new Error("Generation cancelled by user.");
             e.name = "AbortError";
             throw e;
        }
        console.error("Error generating video:", error);
        throw new Error(error.message || "Video generation failed");
    }
};

export const editAdImage = async (
    image: string,
    action: 'upscale' | 'pan' | 'zoom' | 'vary',
    options: {
        direction?: PanDirection | ZoomDirection;
        strength?: VaryStrength;
        level?: ZoomLevel;
    }
): Promise<string> => {
    try {
        const ai = getAIClient();
        const imageData = dataUrlToImageData(image);
        let prompt = '';

        switch (action) {
            case 'upscale':
                prompt = 'Upscale this image to a higher resolution. Enhance details and textures while preserving the original composition and subject matter. The output should be a more detailed and crisp version of the input image.';
                break;
            case 'pan':
                prompt = `This is a frame of a larger scene. Extend the image ${options.direction}, generating new content that logically and seamlessly continues the scene. The original image content should occupy the opposite side of the new, larger image.`;
                break;
            case 'zoom':
                if (options.direction === 'in') {
                   prompt = `Zoom in on the center of the image. The zoom level should be approximately ${options.level}. Preserve high resolution and detail.`;
                } else {
                   prompt = `Zoom out from this image. This image is the center crop of a larger scene. Generate the surrounding context seamlessly.`;
                }
                break;
            case 'vary':
                prompt = `Generate a variation of this image with ${options.strength} changes. Keep the main subject and composition similar but vary the details, lighting, or background slightly.`;
                break;
        }

        const response = await ai.models.generateContent({
             model: 'gemini-2.5-flash-image',
             contents: {
                parts: [
                    { inlineData: { data: imageData.base64, mimeType: imageData.mimeType } },
                    { text: prompt }
                ]
             },
             config: { responseModalities: [Modality.IMAGE] }
        });

        for (const part of response.candidates?.[0]?.content?.parts || []) {
             if (part.inlineData) {
                 return `data:${part.inlineData.mimeType};base64,${part.inlineData.data}`;
             }
        }
        throw new Error("No image returned from edit operation.");

    } catch (error) {
         console.error("Error editing image:", error);
         throw new Error("Failed to edit image.");
    }
};

