    };

    const handleUpscale = () => handleEditAction('upscale', {});
    const handlePan = (direction: PanDirection) => handleEditAction('pan', { direction });
    const handleZoomIn = (level: ZoomLevel) => handleEditAction('zoom', { direction: 'in', level });
    const handleZoomOut = () => handleEditAction('zoom', { direction: 'out', level: '1.5x' });
    const handleVary = (strength: VaryStrength) => handleEditAction('vary', { strength });

    const handleGetSuggestions = async () => {
        setIsGeneratingSuggestions(true);
        setSuggestions([]);
        setError(null);
        try {
            const currentPrompt = promptMode === 'guided'
                ? `Background: ${selectedBackground === 'custom' ? customBackground : selectedBackground}. Placement: ${placement}`
                : fullPrompt;
            if (currentPrompt.trim()) {
                const result = await generateSuggestions(currentPrompt);
                setSuggestions(result);
            }
        } catch (err) {
            setError(err instanceof Error ? `Suggestion Error: ${err.message}`: 'Failed to get suggestions.');
        } finally {
            setIsGeneratingSuggestions(false);
        }
    };

    const handleGenerateCopy = async () => {
        setIsGeneratingCopy(true);
        setAdCopy('');
        setError(null);
        try {
            const sceneDescription = promptMode === 'full' 
                ? fullPrompt 
                : `${placement}. The setting is ${selectedBackground === 'custom' ? customBackground : selectedBackground}`;

            if (productName || slogan || sceneDescription) {
                 const result = await generateAdCopy(productName, slogan, sceneDescription);
                 setAdCopy(result);
            }
        } catch(err) {
             setError(err instanceof Error ? `Ad Copy Error: ${err.message}`: 'Failed to get ad copy.');
        } finally {
            setIsGeneratingCopy(false);
        }
    };

    const handleCopyToClipboard = () => {
        navigator.clipboard.writeText(adCopy).then(() => {
            setCopySuccess(true);
            setTimeout(() => setCopySuccess(false), 2000);
        });
    };

    const applySuggestion = (suggestion: string) => {
        if (promptMode === 'guided') {
            setPlacement(prev => `${prev} ${suggestion}`.trim());
        } else {
            setFullPrompt(prev => `${prev} ${suggestion}`.trim());
        }
        setSuggestions([]);
    };

    const handleClearHistory = () => setHistory([]);

    return (
        <div className="min-h-screen bg-brand-primary text-brand-light font-sans">
            <div className="container mx-auto p-4 md:p-8">
                <header className="relative flex flex-col items-center justify-center mb-8 md:mb-12">
                    <button 
                        onClick={handleReset}
                        className="absolute top-0 right-0 md:top-2 md:right-0 flex items-center gap-2 px-4 py-2 border border-gray-600 hover:border-red-500 hover:text-red-400 text-gray-400 font-semibold rounded-lg transition-all duration-200 text-sm group"
                        aria-label="Reset all fields"
                    >
                        <ArrowPathIcon className="w-4 h-4 group-hover:rotate-180 transition-transform duration-500" />
                        Reset All
                    </button>
                    <h1 className="text-4xl md:text-5xl font-bold text-white mb-2 flex items-center justify-center gap-3 mt-8 md:mt-0">
                        <CameraIcon className="w-10 h-10" />
                        AI Product Ad Generator
                    </h1>
                    <p className="text-lg md:text-xl text-brand-accent">Create stunning, professional ads in seconds.</p>
                </header>

                <main className="grid grid-cols-1 lg:grid-cols-2 gap-8 items-start">
                    <div className="bg-brand-secondary p-6 rounded-2xl shadow-lg flex flex-col gap-6 animate-fade-in">
                        {/* Asset Uploader */}
                        <div>
                            <h2 className="text-2xl font-semibold mb-4 text-white border-b-2 border-brand-accent pb-2">1. Upload Your Assets</h2>
                            <div className="space-y-6">
                                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                                    <div className="h-48"><ImageUploader key={productImage ? 'prod-img-loaded' : 'prod-img-empty'} id="product-image" label="Product Image (Optional)" onImageUpload={setProductImage} initialImage={productImage} /></div>
                                    <div className="h-48"><ImageUploader key={companyLogo ? 'logo-img-loaded' : 'logo-img-empty'} id="company-logo" label="Company Logo (Optional)" onImageUpload={setCompanyLogo} initialImage={companyLogo} /></div>
                                </div>
                                <div>
                                    <label className="text-sm font-medium text-brand-light mb-2 block">Subject/Context Images (up to 8)</label>
                                    <div className="p-4 border-2 border-dashed border-gray-600 rounded-lg bg-brand-primary min-h-[10rem]">
                                        <div className="grid grid-cols-2 sm:grid-cols-4 gap-4">
                                            {subjectImages.map((image, index) => (
                                                <div key={index} className="relative group aspect-square">
                                                    <img src={`data:${image.mimeType};base64,${image.base64}`} alt={`Subject ${index + 1}`} className="w-full h-full object-cover rounded-lg"/>
                                                    <button onClick={() => handleRemoveSubjectImage(index)} className="absolute top-1 right-1 bg-black bg-opacity-60 rounded-full p-1 text-white hover:bg-red-600 transition-all opacity-0 group-hover:opacity-100 focus:opacity-100" aria-label={`Remove subject image ${index + 1}`}><CloseIcon className="w-4 h-4" /></button>
                                                </div>
                                            ))}
                                            {subjectImages.length < 8 && (
                                                <div className="aspect-square"><ImageUploader key={`subject-uploader-${subjectImages.length}`} id="subject-image-uploader" label="Add Image" onImageUpload={handleAddSubjectImage} /></div>
                                            )}
                                        </div>
                                        {subjectImages.length === 0 && <div className="flex items-center justify-center h-full"><p className="text-center text-xs text-gray-500">Add images to provide more context to the AI.</p></div>}
                                    </div>
                                </div>
                            </div>
                        </div>

                        {/* Ad Description */}
                        <div>
                            <h2 className="text-2xl font-semibold mb-4 text-white border-b-2 border-brand-accent pb-2">2. Describe Your Ad</h2>
                            <SloganGenerator productName={productName} onProductNameChange={setProductName} slogan={slogan} onSloganChange={setSlogan} onGenerateSlogans={generateSlogans} />
                        </div>

                        {/* Ad Copy */}
                        <div className="space-y-3">
                             <div className="flex justify-between items-center">
                                <h3 className="text-lg font-medium text-brand-accent">Generate Ad Copy (Optional)</h3>
                                <button onClick={handleGenerateCopy} disabled={isGeneratingCopy || !canGenerate} className="flex items-center gap-2 px-4 py-2 bg-brand-accent hover:bg-indigo-400 text-brand-primary font-bold rounded-lg transition-colors disabled:bg-gray-500 disabled:cursor-not-allowed text-sm">
                                    <SparklesIcon className="w-4 h-4" />
                                    {isGeneratingCopy ? 'Generating...' : 'Generate'}
                                </button>
                            </div>
                            <div className="relative">
                                <textarea value={adCopy} readOnly placeholder="Generate compelling ad copy to match your visuals..." className="w-full p-3 bg-brand-primary border-2 border-gray-600 rounded-lg h-24 resize-none pr-10" />
                                {adCopy && (
                                    <button onClick={handleCopyToClipboard} className="absolute top-2 right-2 p-1.5 text-gray-400 hover:text-white bg-gray-700 hover:bg-gray-600 rounded-md transition-colors" aria-label="Copy to clipboard">
                                        <CopyIcon className="w-5 h-5" />
                                    </button>
                                )}
                            </div>
                            {copySuccess && <p className="text-sm text-green-400 text-center animate-fade-in">Copied to clipboard!</p>}
                        </div>


                        {/* Scene Crafting */}
                        <div>
                            <h2 className="text-2xl font-semibold mb-4 text-white border-b-2 border-brand-accent pb-2">3. Craft Your Scene</h2>
                            <div className="flex bg-brand-primary rounded-lg p-1 mb-4">
                                <button onClick={() => setPromptMode('guided')} className={`w-1/2 p-2 rounded-md text-sm font-semibold transition-colors ${promptMode === 'guided' ? 'bg-indigo-600 text-white' : 'hover:bg-gray-700'}`} aria-pressed={promptMode === 'guided'}>Guided Mode</button>
                                <button onClick={() => setPromptMode('full')} className={`w-1/2 p-2 rounded-md text-sm font-semibold transition-colors ${promptMode === 'full' ? 'bg-indigo-600 text-white' : 'hover:bg-gray-700'}`} aria-pressed={promptMode === 'full'}>Full Prompt</button>
                            </div>

                            {promptMode === 'guided' ? (
                                <div className="space-y-6 animate-fade-in">
                                    <div>
                                        <h3 className="text-lg font-medium mb-3 text-brand-accent">3a. Select a Background</h3>
                                        <BackgroundSelector selected={selectedBackground} onSelect={setSelectedBackground} custom={customBackground} onCustomChange={setCustomBackground}/>
                                    </div>
                                    <div>
                                        <div className="flex justify-between items-center mb-3">
                                            <h3 className="text-lg font-medium text-brand-accent">3b. Describe Placement</h3>
                                            <button onClick={handleGetSuggestions} disabled={isGeneratingSuggestions || (!placement && !customBackground)} className="flex items-center gap-1 text-sm px-2 py-1 bg-brand-accent text-brand-primary font-semibold rounded-md hover:bg-indigo-400 disabled:bg-gray-500 disabled:cursor-not-allowed transition-colors" aria-label="Get AI suggestions for placement"><SparklesIcon className="w-4 h-4" />{isGeneratingSuggestions ? 'Thinking...' : 'Suggestions'}</button>
                                        </div>
                                        <textarea value={placement} onChange={(e) => setPlacement(e.target.value)} placeholder="e.g., A woman with curly hair is happily holding the product, showing it to the camera..." className="w-full p-3 bg-brand-primary border-2 border-gray-600 rounded-lg focus:ring-2 focus:ring-brand-accent focus:border-brand-accent transition duration-200 h-28 resize-none" />
                                        {suggestions.length > 0 && <div className="flex flex-wrap gap-2 mt-2 animate-fade-in">{suggestions.map((s, i) => (<button key={i} onClick={() => applySuggestion(s)} className="px-3 py-1 text-xs bg-brand-primary border border-brand-accent rounded-full hover:bg-brand-accent hover:text-brand-primary transition-colors">+ "{s}"</button>))}</div>}
                                    </div>
                                </div>
                            ) : (
                                <div className="animate-fade-in">
                                    <div className="flex justify-between items-center mb-3">
                                        <h3 className="text-lg font-medium text-brand-accent">Describe the entire scene</h3>
                                        <button onClick={handleGetSuggestions} disabled={isGeneratingSuggestions || !fullPrompt} className="flex items-center gap-1 text-sm px-2 py-1 bg-brand-accent text-brand-primary font-semibold rounded-md hover:bg-indigo-400 disabled:bg-gray-500 disabled:cursor-not-allowed transition-colors" aria-label="Get AI suggestions for full prompt"><SparklesIcon className="w-4 h-4" />{isGeneratingSuggestions ? 'Thinking...' : 'Suggestions'}</button>
                                    </div>
                                    <textarea value={fullPrompt} onChange={(e) => setFullPrompt(e.target.value)} placeholder="e.g., A photorealistic image of the product sitting on a rustic wooden table..." className="w-full p-3 bg-brand-primary border-2 border-gray-600 rounded-lg focus:ring-2 focus:ring-brand-accent focus:border-brand-accent transition duration-200 h-48 resize-none" />
                                    {suggestions.length > 0 && <div className="flex flex-wrap gap-2 mt-2 animate-fade-in">{suggestions.map((s, i) => (<button key={i} onClick={() => applySuggestion(s)} className="px-3 py-1 text-xs bg-brand-primary border border-brand-accent rounded-full hover:bg-brand-accent hover:text-brand-primary transition-colors">+ "{s}"</button>))}</div>}
                                </div>
                            )}

                            <div className="space-y-6 mt-6">
                                <div>
                                    <h3 className="text-lg font-medium mb-3 text-brand-accent">Model & Quality</h3>
                                    <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                                        <div>
                                            <h4 className="text-md font-medium mb-2 text-brand-light">Model Type</h4>
                                            <div className="flex bg-brand-primary rounded-lg p-1">
                                                 <button onClick={() => setModelType('standard')} className={`w-1/2 p-2 rounded-md text-sm font-semibold transition-colors ${modelType === 'standard' ? 'bg-indigo-600 text-white' : 'hover:bg-gray-700'}`}>Standard (Nano)</button>
                                                 <button onClick={() => setModelType('pro')} className={`w-1/2 p-2 rounded-md text-sm font-semibold transition-colors ${modelType === 'pro' ? 'bg-indigo-600 text-white' : 'hover:bg-gray-700'}`}>Pro (Banana)</button>
                                            </div>
                                        </div>
                                         <div>
                                            <h4 className="text-md font-medium mb-2 text-brand-light">Resolution (Pro Only)</h4>
                                            <ImageSizeSelector selected={imageSize} onSelect={setImageSize} disabled={modelType !== 'pro'} />
                                        </div>
                                    </div>
                                </div>

                                <div>
                                    <h3 className="text-lg font-medium mb-3 text-brand-accent">Style</h3>
                                    <StyleSelector selected={selectedStyle} onSelect={setSelectedStyle} />
                                </div>
                                <div>
                                    <h3 className="text-lg font-medium mb-3 text-brand-accent">Mood</h3>
                                    <MoodSelector selected={selectedMood} onSelect={setSelectedMood} />
                                </div>
                                <div>
                                    <h3 className="text-lg font-medium mb-3 text-brand-accent">Texture Realism</h3>
                                    <select
                                        value={cameraSettings.textureDetail}
                                        onChange={(e) => setCameraSettings(prev => ({ ...prev, textureDetail: e.target.value }))}
                                        className="w-full p-3 bg-brand-primary border-2 border-gray-600 rounded-lg focus:ring-2 focus:ring-brand-accent focus:border-brand-accent transition duration-200"
                                        aria-label="Texture Realism"
                                    >
                                        <option value="">Default</option>
                                        <option value="Hyper-detailed macro textures, emphasizing every surface imperfection, pore, and grain.">Hyperrealism (Skin &amp; Surfaces)</option>
                                        <option value="Smooth, clean product textures with a polished, commercial finish.">Commercial Polish</option>
                                        <option value="Rough, weathered textures with visible wear, grit, and age.">Gritty &amp; Weathered (Objects)</option>
                                    </select>
                                </div>
                                <div>
                                    <h3 className="text-lg font-medium mb-3 text-brand-accent">Negative Prompt (Optional)</h3>
                                    <input type="text" value={negativePrompt} onChange={(e) => setNegativePrompt(e.target.value)} placeholder="e.g., no people, blurry, cartoon" className="w-full p-3 bg-brand-primary border-2 border-gray-600 rounded-lg focus:ring-2 focus:ring-brand-accent focus:border-brand-accent transition duration-200"/>
                                </div>
                                <div>
                                    <h3 className="text-lg font-medium mb-3 text-brand-accent">Image Generation Settings</h3>
                                    <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                                        <div>
                                            <h4 className="text-md font-medium mb-2 text-brand-light">Aspect Ratio</h4>
                                            <AspectRatioSelector selected={aspectRatio} onSelect={setAspectRatio} disabled={hasAnyImage && modelType !== 'pro'} />
                                        </div>
                                        <div>
                                            <h4 className="text-md font-medium mb-2 text-brand-light">Variations</h4>
                                            <VariationSelector selected={numberOfVariations} onSelect={setNumberOfVariations} />
                                        </div>
                                    </div>
                                </div>
                                <div className="border-t border-gray-700 pt-6">
                                    <button onClick={() => setShowCameraSettings(!showCameraSettings)} className="flex items-center justify-between w-full text-lg font-medium text-brand-accent hover:text-indigo-400 transition-colors" aria-expanded={showCameraSettings}>
                                        <span className="flex items-center gap-2">
                                            <SettingsIcon className="w-5 h-5" />
                                            Advanced Camera Settings
                                        </span>
                                        <ChevronDownIcon className={`w-5 h-5 transition-transform ${showCameraSettings ? 'rotate-180' : ''}`} />
                                    </button>
                                    {showCameraSettings && (
                                        <div className="mt-4 animate-fade-in">
                                            <CameraSettings settings={cameraSettings} onSettingsChange={setCameraSettings} />
                                        </div>
                                    )}
                                </div>
                                {generatedAds && generatedAds.length > 0 && (
                                    <div className="border-t border-gray-700 pt-6 mt-6 animate-fade-in">
                                        <CreationActions
                                            disabled={isEditing || isLoading}
                                            onUpscale={handleUpscale}
                                            onPan={handlePan}
                                            onZoomIn={handleZoomIn}
                                            onZoomOut={handleZoomOut}
                                            onVary={handleVary}
                                        />
                                    </div>
                                )}
                            </div>
                        </div>

                        {/* Generate Buttons */}
                        <div className="flex flex-col sm:flex-row gap-4 mt-4">
                            <button onClick={handleGenerateAd} disabled={isLoading || !canGenerate} className="w-full bg-indigo-600 hover:bg-indigo-700 text-white font-bold py-3 px-4 rounded-lg transition-all duration-300 disabled:bg-gray-500 disabled:cursor-not-allowed flex items-center justify-center gap-2 text-lg shadow-lg hover:shadow-indigo-500/50"><PhotoIcon className="w-6 h-6" />{isLoading && generationType === 'image' ? 'Generating Image...' : 'Generate Image Ad'}</button>
                            <button onClick={handleGenerateVideo} disabled={isLoading || !canGenerate} className="w-full bg-purple-600 hover:bg-purple-700 text-white font-bold py-3 px-4 rounded-lg transition-all duration-300 disabled:bg-gray-500 disabled:cursor-not-allowed flex items-center justify-center gap-2 text-lg shadow-lg hover:shadow-purple-500/50"><FilmIcon className="w-6 h-6" />{isLoading && generationType === 'video' ? 'Generating Video...' : 'Generate Video Ad'}</button>
                        </div>
                         {isLoading && (
                            <div className="mt-4">
                                <button
                                    onClick={handleStopGeneration}
                                    className="w-full bg-red-600 hover:bg-red-700 text-white font-bold py-3 px-4 rounded-lg transition-all duration-300 flex items-center justify-center gap-2 text-lg shadow-lg hover:shadow-red-500/50"
                                    aria-label="Stop generation"
                                >
                                    <StopIcon className="w-6 h-6" />
                                    Stop Generation
                                </button>
                            </div>
                        )}
                    </div>

                    <div className="lg:sticky lg:top-8 lg:h-fit flex flex-col gap-8">
                        <div className="bg-brand-secondary p-6 rounded-2xl shadow-lg animate-fade-in flex flex-col" style={{ animationDelay: '200ms' }}>
                            <AdDisplay 
                                generatedAds={generatedAds} 
                                generatedVideo={generatedVideo} 
                                isLoading={isLoading} 
                                isEditing={isEditing}
                                error={error} 
                                generationType={generationType} 
                                videoLoadingMessage={videoLoadingMessage}
                                activeIndex={activeAdIndex}
                                onSelectVariation={setActiveAdIndex}
                            />
                        </div>
                    </div>
                </main>
                <HistoryDisplay 
                    history={history} 
                    onImageSelect={(url) => { setGeneratedAds([url]); setGeneratedVideo(null); }} 
                    onClearHistory={handleClearHistory} 
                />
            </div>
        </div>
    );
};

export default App;

import React, { useState, useEffect } from 'react';
import { SparklesIcon } from './icons';
import { ExportControls } from './ExportControls';
import type { PanDirection, ZoomDirection } from '../types';

interface AdDisplayProps {
    generatedAds: string[] | null;
    generatedVideo: string | null;
    isLoading: boolean;
    isEditing: boolean;
    error: string | null;
    generationType: 'image' | 'video' | null;
    videoLoadingMessage: string;
    activeIndex: number;
    onSelectVariation: (index: number) => void;
}

type PreviewMode = 'default' | 'story' | 'post';

const LoadingSpinner: React.FC<{text?: string}> = ({text}) => (
    <div className="flex flex-col items-center justify-center">
        <svg className="animate-spin h-8 w-8 text-white" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
            <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
            <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
        </svg>
        {text && <p className="mt-4 text-xl font-semibold text-white">{text}</p>}
    </div>
);

const SocialPreviewWrapper: React.FC<{ mode: PreviewMode; children: React.ReactNode }> = ({ mode, children }) => {
    if (mode === 'story') {
        return (
            <div className="w-[280px] h-[500px] bg-black border-4 border-gray-700 rounded-3xl p-2 flex flex-col shadow-2xl">
                <div className="flex-grow bg-gray-900 rounded-2xl overflow-hidden relative">
                    {children}
                    <div className="absolute top-2 left-2 flex items-center gap-2">
                         <div className="w-8 h-8 bg-gray-500 rounded-full border-2 border-white"></div>
                         <div className="w-20 h-3 bg-gray-500 rounded-full"></div>
                    </div>
                </div>
            </div>
        );
    }
    if (mode === 'post') {
        return (
             <div className="w-full max-w-md bg-[#050505] border border-gray-700 rounded-xl p-3 flex flex-col gap-3 shadow-2xl">
                 <div className="flex items-center gap-2">
                     <div className="w-10 h-10 bg-gray-600 rounded-full"></div>
                     <div className="w-24 h-4 bg-gray-600 rounded-full"></div>
                 </div>
                <div className="w-full bg-gray-900 rounded-lg overflow-hidden aspect-square relative">{children}</div>
                 <div className="w-full h-4 bg-gray-600 rounded-full"></div>
                 <div className="w-3/4 h-4 bg-gray-600 rounded-full"></div>
            </div>
        )
    }
    return <>{children}</>;
};


export const AdDisplay: React.FC<AdDisplayProps> = ({ 
    generatedAds, generatedVideo, isLoading, isEditing, error, generationType, videoLoadingMessage,
    activeIndex, onSelectVariation
}) => {
    const [previewMode, setPreviewMode] = useState<PreviewMode>('default');

    useEffect(() => {
        onSelectVariation(0);
        setPreviewMode('default');
    }, [generatedAds, generatedVideo]);

    const activeAd = generatedAds ? generatedAds[activeIndex] : null;

    const renderContent = () => {
        if (isLoading) {
            return (
                <div className="flex flex-col items-center justify-center h-full w-full text-center">
                    <LoadingSpinner text={generationType === 'video' ? videoLoadingMessage : 'Generating your ad...'}/>
                    <p className="mt-2 text-sm text-gray-400">
                      {generationType === 'video' ? 'Video generation can take a few minutes.' : 'This might take a moment.'}
                    </p>
                </div>
            );
        }

        if (error) {
            return (
                <div className="flex flex-col items-center justify-center h-full w-full text-center p-4">
                    <div className="bg-red-900/50 border border-red-700 rounded-lg p-6 max-w-md">
                        <h3 className="text-xl font-bold text-red-300 mb-2">Operation Failed</h3>
                        <p className="text-red-300">{error}</p>
                    </div>
                </div>
            );
        }

        if (activeAd) {
            return (
                 <div className="w-full h-full flex flex-col lg:flex-row gap-6">
                    {/* Variations Column (Left on Desktop, Bottom on Mobile) */}
                    {generatedAds && generatedAds.length > 1 && (
                         <div className="flex-shrink-0 lg:w-20 order-2 lg:order-1">
                             <h4 className="text-xs font-bold mb-3 text-brand-accent uppercase tracking-wider lg:text-center">Variants</h4>
                             <div className="flex lg:flex-col justify-start lg:justify-center gap-3 overflow-x-auto lg:overflow-y-visible pb-2 lg:pb-0 scrollbar-hide">
                                 {generatedAds.map((ad, index) => (
                                     <button 
                                        key={index} 
                                        onClick={() => onSelectVariation(index)} 
                                        className={`flex-shrink-0 w-16 h-16 rounded-lg overflow-hidden border-2 transition-all duration-200 transform hover:scale-105 active:scale-95 ${activeIndex === index ? 'border-brand-accent shadow-lg shadow-indigo-500/20 ring-2 ring-indigo-500/20' : 'border-gray-700 hover:border-gray-500'}`}
                                     >
                                         <img src={ad} alt={`Thumbnail ${index + 1}`} className="w-full h-full object-cover" />
                                     </button>
                                 ))}
                             </div>
                         </div>
                    )}

                    <div className="relative flex-grow flex items-center justify-center animate-fade-in group order-1 lg:order-2 overflow-hidden">
                         <SocialPreviewWrapper mode={previewMode}>
                            <img src={activeAd} alt={`Generated ad variation ${activeIndex + 1}`} className="object-contain w-full h-full max-h-[70vh]" />
                        </SocialPreviewWrapper>
                        <ExportControls generatedAd={activeAd} generatedVideo={null} />
                        {isEditing && (
                            <div className="absolute inset-0 bg-black bg-opacity-70 flex items-center justify-center rounded-lg z-20">
                                <LoadingSpinner text="Editing image..." />
                            </div>
                        )}
                    </div>
                </div>
            );
        }

        if (generatedVideo) {
            return (
                <div className="w-full h-full flex flex-col gap-4">
                    <div className="relative w-full flex-grow animate-fade-in flex items-center justify-center">
                        <SocialPreviewWrapper mode={previewMode}>
                            <video src={generatedVideo} controls autoPlay loop className="object-contain w-full h-full max-h-[70vh]" />
                        </SocialPreviewWrapper>
                        <ExportControls generatedAd={null} generatedVideo={generatedVideo} />
                    </div>
                </div>
            )
        }

        return (
            <div className="flex flex-col items-center justify-center h-full w-full text-center text-gray-400 py-20">
                <SparklesIcon className="w-16 h-16 mb-4 animate-pulse text-brand-accent" />
                <h3 className="text-2xl font-bold text-white mb-2">Your Ad Will Appear Here</h3>
                <p className="max-w-xs mx-auto">Fill out the details on the left and click "Generate" to see the magic happen!</p>
            </div>
        );
    };

    const hasContent = (generatedAds && generatedAds.length > 0) || generatedVideo;

    return (
        <div className="w-full h-full flex flex-col gap-4">
            <div className="w-full min-h-[50vh] bg-brand-primary rounded-2xl flex items-center justify-center p-6 relative overflow-hidden border border-gray-800">
                {renderContent()}
            </div>
            {hasContent && (
                <div className="flex-shrink-0 bg-brand-primary rounded-xl p-3 flex items-center justify-center gap-2 border border-gray-800">
                    <span className="text-xs font-bold text-brand-accent uppercase tracking-widest mr-2">Preview Mode</span>
                    <div className="flex bg-brand-secondary rounded-lg p-1">
                        <button onClick={() => setPreviewMode('default')} className={`px-4 py-1.5 text-xs font-semibold rounded-md transition-all ${previewMode === 'default' ? 'bg-indigo-600 text-white shadow-md' : 'text-gray-400 hover:text-white hover:bg-gray-700'}`}>Default</button>
                        <button onClick={() => setPreviewMode('story')} className={`px-4 py-1.5 text-xs font-semibold rounded-md transition-all ${previewMode === 'story' ? 'bg-indigo-600 text-white shadow-md' : 'text-gray-400 hover:text-white hover:bg-gray-700'}`}>Story</button>
                        <button onClick={() => setPreviewMode('post')} className={`px-4 py-1.5 text-xs font-semibold rounded-md transition-all ${previewMode === 'post' ? 'bg-indigo-600 text-white shadow-md' : 'text-gray-400 hover:text-white hover:bg-gray-700'}`}>Post</button>
                    </div>
                </div>
            )}
        </div>
    );
};
